const KEY='sorriso-demo-v3';let db;try{db=JSON.parse(localStorage.getItem(KEY));if(db?.version!==3)db=seed()}catch{db=seed()}
let route='inicio',selectedPatient='p1',patientTab='visao',selectedDate=today,patientQuery='',patientStatus='Todos',patientView='grid',agendaStatus='Todos',financeFilter='Todos',documentPatient='p1',documentType='Declaração de comparecimento',callState=null,callTimer=null,smile={patient:'p5',shade:'B1',alignment:65,shape:50,compare:50,photo:null,generated:false},chartPeriod='Semana',tourStep=-1;
function save(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch{toast('Não foi possível salvar no navegador. Libere espaço e tente novamente.')}}
function activity(text,ico='check'){db.activity.unshift({text,date:today,icon:ico});db.activity=db.activity.slice(0,20);save()}
function patient(id){return db.patients.find(p=>p.id===id)||db.patients[0]}
function toast(text){const el=$('#toast');el.innerHTML=icon('check',15)+`<span>${esc(text)}</span>`;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3600)}
const navItems=[['inicio','home','Visão geral'],['agenda','calendar','Agenda'],['pacientes','users','Pacientes'],['prontuarios','record','Prontuários'],['sorriso','sparkles','Sorriso IA','DEMO'],['teleconsultas','video','Teleconsultas'],['documentos','file','Documentos'],['financeiro','wallet','Financeiro'],['relatorios','chart','Relatórios'],['configuracoes','settings','Configurações']];
function renderNav(){const active=route==='paciente'?'pacientes':route;$('#navigation').innerHTML=navItems.map(([r,i,t,tag],n)=>`${n===7?'<div class="nav-separator"></div>':''}<a href="#${r}" class="nav-item ${active===r?'active':''}" ${active===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${tag?`<span class="nav-tag">${tag}</span>`:''}</a>`).join('');$('#breadcrumb-title').textContent=route==='paciente'?'Perfil do paciente':navItems.find(n=>n[0]===route)?.[2]||'Visão geral';$('#search-icon').innerHTML=icon('heart',18);$('#bell-icon').innerHTML=icon('bell',18);$('.clinic>span:nth-child(2)').innerHTML=`${esc(db.settings.clinic)}<small>Ambiente de apresentação</small>`;$('.profile>span:nth-child(2)').innerHTML=`${esc(db.settings.doctor)}<small>Administradora · Demo</small>`}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`}
function card(title,subtitle,body,action='',cls=''){return `<section class="card ${cls}"><div class="card-header"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>${body}</section>`}
function kpi(label,value,ico,bottom,change=''){return `<div class="kpi"><div class="kpi-top"><span>${label}</span><span class="kpi-icon">${icon(ico,16)}</span></div><div class="kpi-value">${value}</div><div class="kpi-bottom">${change?`<span class="growth">${change}</span>`:''}${bottom}</div></div>`}
function todayAppointments(){return db.appointments.filter(a=>a.date===today&&a.status!=='Cancelado').sort((a,b)=>a.time.localeCompare(b.time))}
function patientRow(p,compact=false){return `<tr><td><button class="person-cell row-action" data-action="patient" data-id="${p.id}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.email)}</small></span></button></td>${compact?'':`<td>${esc(p.phone)}</td>`}<td>${esc(p.procedure||'Avaliação inicial')}</td><td>${badge(p.status)}</td><td><button class="row-action" data-action="patient" data-id="${p.id}" aria-label="Abrir ${esc(p.name)}">${icon('arrow',14)}</button></td></tr>`}
function activityChart(){const week=chartPeriod==='Semana';const values=week?[7,10,8,12,9,5,2]:[32,46,39,53,48,41];const labels=week?['Seg','Ter','Qua','Qui','Sex','Sáb','Dom']:['Mai','Jun','Jul','Ago','Set','Out'];return `<div class="chart-legend"><span><i></i> Consultas</span><span><i></i> Retornos</span><span style="margin-left:auto;color:#aab39d">Histórico ilustrativo</span></div><div class="bar-chart"><span class="chart-y top">${week?15:60}</span><span class="chart-y middle">${week?8:30}</span><span class="chart-y bottom">0</span>${values.map((v,i)=>`<div class="bar-pair"><div class="bar" style="height:${v/(week?15:60)*100}%" title="${v} consultas ilustrativas"></div><div class="bar light" style="height:${v/(week?15:60)*58}%"></div><span class="bar-label">${labels[i]}</span></div>`).join('')}</div><div class="chart-summary"><span>Uma visão do ritmo da sua clínica</span><strong>↑ 12,8% <span class="muted">no cenário de exemplo</span></strong></div>`}
function toothArt(){return `<svg viewBox="0 0 230 190" fill="none"><ellipse cx="125" cy="159" rx="69" ry="13" fill="#102e2566"/><path d="M83 34c18-14 29 4 42 1 17-5 33-9 42 4 15 21-3 58-9 77-7 22-12 36-22 33-10-3-7-42-16-42-10 0-8 42-19 42-10 0-14-18-21-38-8-25-20-58 3-77Z" fill="#e9eedb"/><path d="M100 39c14 6 18 4 28 1" stroke="#b8ca9e" stroke-width="4" stroke-linecap="round"/><path d="M90 50c-8 10-1 30 3 39" stroke="white" stroke-width="5" stroke-linecap="round" opacity=".8"/><path d="m185 44 4 10 11 4-11 4-4 11-4-11-11-4 11-4Zm-126 63 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z" fill="#c3d695"/><circle cx="57" cy="48" r="3" fill="#87a274"/><circle cx="178" cy="136" r="4" fill="#87a274"/></svg>`}
function renderHome(){const appointments=todayAppointments();const upcoming=appointments.slice(0,4);const hour=new Date().getHours();const greeting=hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite';return heading(`${greeting}, Dra. Helena <span style="color:#b1bd96;font-weight:400">✺</span>`,'Um novo dia para transformar sorrisos. Vamos começar?',`<span class="date-chip">${icon('calendar',13)}${prettyDate(today,{day:'numeric',month:'long',year:'numeric'})}</span>${btn('Novo agendamento','new-appointment','plus','primary')}`)+`<section class="hero-banner"><div class="hero-text"><div class="eyebrow">${icon('sparkles',12)} TECNOLOGIA A SERVIÇO DO CUIDADO</div><h2>O próximo sorriso começa<br>com um <em>novo olhar.</em></h2><p>Explore possibilidades estéticas e encante seus pacientes.</p><button class="button lime" data-route="sorriso">Explorar Sorriso IA ${icon('arrow',13)}</button></div><div class="hero-art">${toothArt()}</div><span class="hero-tag">${icon('shield',13)} Planejamento mais humano</span></section><div class="kpi-grid home-kpis">${kpi('Pacientes cadastrados',db.patients.length.toString().padStart(2,'0'),'users','na sua clínica',`${db.patients.filter(p=>p.status==='Ativo').length} ativos`)}${kpi('Consultas hoje',appointments.length.toString().padStart(2,'0'),'calendar',`${appointments.filter(a=>a.status==='Confirmado').length} confirmadas`)}${kpi('Sorrisos planejados',db.simulations.length.toString().padStart(2,'0'),'sparkles','simulações salvas no navegador')}</div><div class="home-agenda">${card('Agenda de hoje',`${appointments.length} atendimentos no seu dia`,`<div class="card-body">${upcoming.map(a=>{const p=patient(a.patient);return `<div class="appointment-row"><span class="appointment-time">${a.time}</span>${avatar(p)}<div class="appointment-info"><strong>${esc(p.name)}</strong><small>${esc(a.procedure)}</small></div>${badge(a.status)}</div>`}).join('')||empty('Agenda livre','Adicione o primeiro atendimento de hoje.')}</div>`,`<button class="card-link" data-route="agenda">Ver agenda ${icon('arrow',12)}</button>`)}</div><div class="lower-grid">${card('Seus pacientes','Cuidado contínuo, relações que importam',`<div class="table-wrap"><table><thead><tr><th>Paciente</th><th>Último procedimento</th><th>Status</th><th></th></tr></thead><tbody>${db.patients.slice(0,3).map(p=>patientRow(p,true)).join('')}</tbody></table></div>`,`<button class="card-link" data-route="pacientes">Ver todos ${icon('arrow',12)}</button>`)}<section class="insight-card"><div class="eyebrow">${icon('video',12)} CUIDADO ALÉM DO CONSULTÓRIO</div><h3>Mais perto, mesmo<br>à distância.</h3><p>Apresente um acompanhamento acolhedor com a sala de teleconsulta.</p><button class="button" data-route="teleconsultas">Abrir teleconsultas ${icon('arrow',13)}</button><div class="insight-orb">◡</div></section></div>`}
function patientCards(){const list=db.patients.filter(p=>(patientStatus==='Todos'||p.status===patientStatus)&&`${p.name} ${p.email} ${p.phone}`.toLowerCase().includes(patientQuery.toLowerCase()));if(!list.length)return empty('Nenhum paciente encontrado','Tente outro nome ou ajuste o filtro.');return patientView==='grid'?`<div class="patient-grid">${list.map(p=>`<article class="patient-card"><div class="patient-card-top">${avatar(p)}${badge(p.status)}</div><h3>${esc(p.name)}</h3><span class="muted" style="font-size:10px">${esc(p.procedure)}</span><div class="patient-contact">${icon('phone',13)}${esc(p.phone)}</div><div class="patient-contact">${icon('mail',13)}${esc(p.email)}</div><div class="patient-card-footer"><span>Última visita: ${prettyDate(p.last)}</span><button class="card-link" data-action="patient" data-id="${p.id}">Ver perfil ${icon('arrow',12)}</button></div></article>`).join('')}</div>`:`<div class="card table-wrap"><table><thead><tr><th>Paciente</th><th>Telefone</th><th>Procedimento</th><th>Status</th><th></th></tr></thead><tbody>${list.map(p=>patientRow(p)).join('')}</tbody></table></div>`}
function renderPatients(){return heading('Pacientes','Cada sorriso tem uma história. Conheça quem confia em você.',btn('Novo paciente','new-patient','plus','primary'))+`<div class="section-toolbar"><div class="input-search">${icon('search',15)}<input id="patient-search" placeholder="Buscar por nome, telefone ou e-mail" value="${esc(patientQuery)}" aria-label="Buscar paciente"></div><div class="filters"><select id="patient-status" aria-label="Filtrar status"><option ${patientStatus==='Todos'?'selected':''}>Todos</option><option ${patientStatus==='Ativo'?'selected':''}>Ativo</option><option ${patientStatus==='Inativo'?'selected':''}>Inativo</option></select><div class="segmented"><button data-action="patient-view" data-value="grid" aria-label="Exibir cartões" class="${patientView==='grid'?'active':''}">${icon('grid',14)}</button><button data-action="patient-view" data-value="list" aria-label="Exibir lista" class="${patientView==='list'?'active':''}">${icon('list',14)}</button></div></div></div><div id="patients-list">${patientCards()}</div><p class="muted" style="font-size:9px;margin-top:20px">${db.patients.length} pacientes fictícios · Alterações ficam salvas neste navegador</p>`}
function renderAgenda(){const dates=Array.from({length:7},(_,i)=>addDay(selectedDate,i-3));const list=db.appointments.filter(a=>a.date===selectedDate&&(agendaStatus==='Todos'||a.status===agendaStatus)).sort((a,b)=>a.time.localeCompare(b.time));return heading('Sua agenda, com leveza.','Organize os atendimentos e reserve tempo para cuidar.',btn('Novo agendamento','new-appointment','plus','primary'))+`<div class="section-toolbar"><div class="heading-actions">${btn('','prev-day','chevron','','aria-label="Dia anterior" style="transform:rotate(180deg)"')}<strong style="font-size:13px">${prettyDate(selectedDate,{day:'numeric',month:'long',year:'numeric'})}</strong>${btn('','next-day','chevron','','aria-label="Próximo dia"')}${btn('Hoje','today','','ghost')}</div><div class="filters"><select id="agenda-status" aria-label="Filtrar agendamentos">${['Todos','Confirmado','Pendente','Concluído','Cancelado'].map(s=>`<option ${agendaStatus===s?'selected':''}>${s}</option>`).join('')}</select></div></div><section class="card"><div class="calendar-strip">${dates.map(d=>`<button class="calendar-day ${d===selectedDate?'active':''}" data-action="select-day" data-date="${d}"><span>${prettyDate(d,{weekday:'short'}).replace('.','').toUpperCase()}</span><strong>${new Date(d+'T12:00').getDate()}</strong><span>${db.appointments.filter(a=>a.date===d&&a.status!=='Cancelado').length} consultas</span></button>`).join('')}</div><div class="agenda-list">${list.map(a=>{const p=patient(a.patient);return `<div class="agenda-item"><div class="time">${a.time}<small>${a.duration} min</small></div>${avatar(p)}<div class="agenda-item-main"><h3>${esc(p.name)}</h3><p>${esc(a.procedure)} · ${esc(a.professional)} ${a.type==='Teleconsulta'?' · Online':''}</p></div>${badge(a.status)}${btn('Detalhes','appointment-detail','','',`data-id="${a.id}"`)}</div>`}).join('')||empty('Seu dia tem espaço para novos sorrisos.','Nenhum atendimento nesta data.',btn('Agendar consulta','new-appointment','plus','primary'))}</div></section>`}
function renderRecords(){return heading('Prontuários','Histórias de cuidado, organizadas em um só lugar.')+`<div class="notice">${icon('info',16)}Prontuários demonstrativos. Os registros e o odontograma não representam avaliações clínicas reais.</div><div class="card table-wrap"><table><thead><tr><th>Paciente</th><th>Último registro</th><th>Evoluções</th><th>Plano de tratamento</th><th></th></tr></thead><tbody>${db.patients.map(p=>`<tr><td><div class="person-cell">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>Prontuário ${p.id.replace('p','').toUpperCase().slice(0,7)}</small></span></div></td><td>${prettyDate(p.last)}</td><td>${p.history.length} registros</td><td>${p.treatments.length} procedimentos</td><td>${btn('Abrir prontuário','open-record','record','',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div>`}
function renderPatient(){const p=patient(selectedPatient);const age=Math.max(0,Math.floor((Date.now()-new Date(p.birth+'T12:00'))/31557600000));let body='';if(patientTab==='visao')body=`<div class="two-columns">${card('Informações do paciente','Dados fictícios para apresentação',`<div class="card-body"><div class="detail-grid">${[['Data de nascimento',`${prettyDate(p.birth,{day:'2-digit',month:'2-digit',year:'numeric'})} · ${age} anos`],['Telefone',p.phone],['E-mail',p.email],['Plano',p.plan],['Alergias e atenção',p.allergies],['Status',p.status]].map(([l,v])=>`<div class="detail-field"><small>${l}</small><span>${esc(v)}</span></div>`).join('')}</div><div class="form-section">Observações</div><p style="font-size:11px;color:#8b9a7b">${esc(p.notes||'Nenhuma observação cadastrada.')}</p></div>`)}${card('Próximos atendimentos','Continuidade do cuidado',`<div class="card-body">${db.appointments.filter(a=>a.patient===p.id&&a.date>=today&&a.status!=='Cancelado').slice(0,4).map(a=>`<div class="appointment-row"><span class="kpi-icon">${icon(a.type==='Teleconsulta'?'video':'calendar',16)}</span><div class="appointment-info"><strong>${esc(a.procedure)}</strong><small>${prettyDate(a.date)} · ${a.time}</small></div>${badge(a.status)}</div>`).join('')||'<p class="muted" style="font-size:11px">Nenhum atendimento agendado.</p>'}${btn('Agendar retorno','new-appointment','plus','',`data-patient="${p.id}"`)}</div>`)}</div>`;if(patientTab==='evolucao')body=card('Linha do tempo','Uma visão da jornada do paciente',`<div class="card-body" style="padding-top:10px">${p.history.map(h=>`<div class="timeline-item"><small>${prettyDate(h.date,{day:'numeric',month:'long',year:'numeric'})}</small><h4>${esc(h.title)}</h4><p>${esc(h.text)}</p></div>`).join('')||empty('A história começa aqui','Adicione uma evolução demonstrativa.')}</div>`,btn('Nova evolução','new-note','plus','primary',`data-id="${p.id}"`));if(patientTab==='odontograma'){const upper=[18,17,16,15,14,13,12,11,21,22,23,24,25,26,27,28],lower=[48,47,46,45,44,43,42,41,31,32,33,34,35,36,37,38];body=card('Odontograma interativo','Clique em um dente para alternar: íntegro → acompanhamento → tratamento.',`<div class="card-body"><div class="chart-legend"><span><i style="background:#dce7d0"></i>Acompanhamento</span><span><i style="background:#e8c89a"></i>Tratamento</span><span>Demonstrativo</span></div><div class="tooth-grid">${[...upper,...lower].map(n=>`<button class="tooth ${p.teeth[n]||''}" data-action="tooth" data-tooth="${n}" aria-label="Dente ${n}: ${p.teeth[n]==='marked'?'acompanhamento':p.teeth[n]==='treatment'?'tratamento':'íntegro'}">${icon('tooth',25)}<span>${n}</span></button>`).join('')}</div><div class="notice" style="margin:0">${icon('info',15)}As marcações são fictícias e ficam salvas apenas neste navegador.</div></div>`)}if(patientTab==='plano')body=card('Plano de tratamento','Procedimentos e valores de exemplo',`<div class="card-body">${p.treatments.map((t,i)=>`<div class="treatment-plan"><div><h4>${esc(t.name)}</h4><small>${esc(t.status)}</small></div><strong>${money(t.value)}</strong></div>`).join('')||'<p class="muted">Nenhum procedimento adicionado.</p>'}<div class="plan-total"><span>Total planejado</span><strong>${money(p.treatments.reduce((s,t)=>s+t.value,0))}</strong></div></div>`,btn('Adicionar procedimento','new-treatment','plus','',`data-id="${p.id}"`));return heading('Perfil do paciente','Uma visão completa de cada história.',`<button class="button ghost" data-route="pacientes">Voltar</button>${btn('Editar paciente','edit-patient','edit','primary',`data-id="${p.id}"`)}`)+`<div class="profile-header">${avatar(p)}<div><h2>${esc(p.name)}</h2><p>${esc(p.procedure)} · ${esc(p.phone)} · ${badge(p.status)}</p></div></div><div class="tabs">${[['visao','Visão geral'],['evolucao','Evolução clínica'],['odontograma','Odontograma'],['plano','Plano de tratamento']].map(([t,l])=>`<button class="tab ${patientTab===t?'active':''}" data-action="patient-tab" data-tab="${t}">${l}</button>`).join('')}</div>${body}`}
function smileSVG(after=false){const whiteness=after?({A1:'#fffcf4',B1:'#fffffc',A2:'#f6ebd5',A3:'#ebd8b6'}[smile.shade]||'#fff'):'#e5d0a5';const align=after?smile.alignment/100:0;const shape=after?smile.shape/100:.2;return `<svg viewBox="0 0 600 380" xmlns="http://www.w3.org/2000/svg"><defs><radialGradient id="skin${after}"><stop stop-color="#f2d8c1"/><stop offset="1" stop-color="#c9a18b"/></radialGradient><linearGradient id="lip${after}" x2="0" y2="1"><stop stop-color="#b87573"/><stop offset=".5" stop-color="#d39890"/><stop offset="1" stop-color="#b97773"/></linearGradient></defs><rect width="600" height="380" fill="url(#skin${after})"/><path d="M70 180Q160 100 250 136Q300 145 350 136Q440 100 530 180Q450 282 300 285Q150 282 70 180Z" fill="url(#lip${after})"/><path d="M97 182Q190 160 300 165Q410 160 503 182Q420 255 300 251Q180 255 97 182Z" fill="#663d39"/><path d="M115 179Q300 145 485 179L470 201Q300 225 130 201Z" fill="#b97f79"/>${Array.from({length:10},(_,i)=>{const x=119+i*36.2;const central=i>=3&&i<=6;const h=central?66:51;const wobble=after?(1-align)*[5,-4,6,0,-5,4,0,5,-3,2][i]:[5,-4,6,0,-5,4,0,5,-3,2][i];return `<rect x="${x}" y="${164+Math.abs(i-4.5)*1.7+wobble}" width="${central?37:35}" height="${h}" rx="${7+shape*7}" fill="${whiteness}" stroke="#c6b89b" stroke-width="1.1" transform="rotate(${after?(1-align)*[3,-2,2,-2,1,-1,2,-3,2,-3][i]:[3,-2,2,-2,1,-1,2,-3,2,-3][i]} ${x+18} 185)"/>`}).join('')}<path d="M115 181Q300 142 485 181" fill="none" stroke="#d4948c" stroke-width="8" stroke-linecap="round"/><path d="M133 229Q300 268 468 229" fill="none" stroke="#cf9187" stroke-width="17" stroke-linecap="round"/><path d="M133 250Q300 302 467 250" fill="none" stroke="#f3c7b0" stroke-width="2" opacity=".3"/><text x="300" y="341" text-anchor="middle" fill="#896f60" font-family="Arial" font-size="11" letter-spacing="2">ILUSTRAÇÃO DEMONSTRATIVA</text></svg>`}
function smileStage(){return `<div class="smile-before">${smile.photo?`<img src="${smile.photo}" alt="Imagem enviada para demonstração">`:smileSVG(false)}</div><div class="smile-after">${smile.photo?`<img src="${smile.photo}" alt="Ajuste visual ilustrativo da imagem" style="filter:brightness(${1.02+smile.alignment/1000}) saturate(.92)">`:smileSVG(true)}</div><span class="compare-label left">Original ilustrativo</span><span class="compare-label right">Prévia demonstrativa</span><div class="compare-line"><span>↔</span></div><input class="smile-range" id="compare-slider" type="range" min="1" max="99" value="${smile.compare}" aria-label="Comparar antes e depois">`}
function renderSmile(){return heading('Um novo olhar para cada sorriso.','Explore o potencial de um planejamento visual, junto com seu paciente.',`<span class="badge blue">Simulação de interface</span>`)+`<div class="notice">${icon('sparkles',16)}Esta é uma demonstração visual, sem processamento de IA. A ilustração e os ajustes não preveem resultados clínicos.</div><div class="smile-layout">${card('Estúdio do sorriso','Arraste a divisória para comparar as possibilidades.',`<div class="smile-stage" id="smile-stage" style="--compare:${smile.compare}%">${smileStage()}</div><div class="simulation-result"><div><h3 id="simulation-title">${smile.generated?'Prévia demonstrativa pronta':'Seu planejamento começa aqui'}</h3><p>Ajuste os parâmetros ao lado e salve sua apresentação.</p></div>${btn('Salvar prévia','save-simulation','download','',smile.generated?'':'disabled')}</div>`)}${card('Personalize a prévia','Pequenos ajustes, novas perspectivas.',`<div class="card-body"><label class="field"><span>Paciente</span><select id="smile-patient">${patientOptions(smile.patient)}</select></label><div class="form-section">Imagem de referência</div><label class="upload-zone">${icon('upload',23)}${smile.photo?'Trocar imagem':'Adicionar imagem do dispositivo'}<small>JPG ou PNG · Até 4 MB · Não envie fotos reais de pacientes</small><input type="file" id="smile-photo" accept="image/jpeg,image/png" hidden></label>${smile.photo?btn('Usar ilustração de exemplo','reset-photo','','ghost'):''}<div class="form-section">Tonalidade ilustrativa</div><div class="shade-options">${[['A3','#e9d8b6'],['A2','#f6ebd5'],['A1','#fffcf4'],['B1','#fffffc']].map(([s,c])=>`<button class="shade ${smile.shade===s?'active':''}" style="background:${c}" data-action="shade" data-value="${s}" aria-label="Tonalidade ${s}"><span>${s}</span></button>`).join('')}</div><div class="slider-control" style="margin-top:32px"><label for="alignment">Alinhamento ilustrativo <span id="alignment-value">${smile.alignment}%</span></label><input type="range" id="alignment" min="0" max="100" value="${smile.alignment}"></div><div class="slider-control"><label for="shape">Suavidade do formato <span id="shape-value">${smile.shape}%</span></label><input type="range" id="shape" min="0" max="100" value="${smile.shape}"></div>${btn('Gerar prévia demonstrativa','generate-smile','sparkles','primary','style="width:100%"')}<div id="simulation-progress"></div></div>`)}</div>${card('Planejamentos salvos','Sua galeria de demonstração',`<div class="table-wrap"><table><thead><tr><th>Paciente</th><th>Data</th><th>Tonalidade</th><th>Alinhamento</th><th></th></tr></thead><tbody>${db.simulations.map(s=>`<tr><td><div class="person-cell">${avatar(patient(s.patient))}<strong>${esc(patient(s.patient).name)}</strong></div></td><td>${prettyDate(s.date)}</td><td>${esc(s.shade)}</td><td>${s.alignment}%</td><td>${btn('Abrir prévia','open-simulation','','',`data-id="${s.id}"`)}</td></tr>`).join('')||'<tr><td colspan="5">Nenhuma prévia salva ainda.</td></tr>'}</tbody></table></div>`,'','settings-section').replace('class="card settings-section"','class="card settings-section" style="margin-top:22px"')}`}
function patientOptions(selected=''){return db.patients.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('')}
function renderTeleconsultas(){const calls=db.appointments.filter(a=>a.type==='Teleconsulta'&&a.status!=='Cancelado');return heading('Cuidado que ultrapassa distâncias.','Uma experiência de atendimento online, pronta para apresentar.',btn('Agendar teleconsulta','new-teleconsult','plus','primary'))+`<div class="notice">${icon('video',16)}Sala demonstrativa. Não há conexão de vídeo, áudio, câmera ou comunicação com outras pessoas.</div>${callState?renderCall():`<div class="kpi-grid">${kpi('Teleconsultas',calls.length.toString().padStart(2,'0'),'video','agendamentos online')}${kpi('Confirmadas',calls.filter(a=>a.status==='Confirmado').length.toString().padStart(2,'0'),'check','prontas para acompanhamento')}${kpi('Disponibilidade','Online','activity','sala simulada disponível')}${kpi('Privacidade','Local','shield','sem transmissão de mídia')}</div><div class="module-grid">${calls.map(a=>{const p=patient(a.patient);return `<article class="module-card"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px">${avatar(p)}${badge(a.status)}</div><h3>${esc(p.name)}</h3><p>${esc(a.procedure)}<br>${prettyDate(a.date,{day:'numeric',month:'long'})} · ${a.time} · ${a.duration} min<br>${esc(a.professional)}</p><div style="display:flex;gap:7px">${btn('Entrar na sala demo','start-call','video','primary',`data-id="${a.id}"`)}</div></article>`}).join('')||empty('Nenhuma teleconsulta agendada','Crie um agendamento online para começar.')}</div>`}`}
function renderCall(){const p=patient(callState.patient);return `<div class="two-columns"><section><div class="call-stage"><div class="call-bg"></div><div class="call-status"><i></i> Sala de demonstração · Sem transmissão</div><div class="call-patient">${avatar(p)}<h3>${esc(p.name)}</h3><p>${callState.camera?'Participante fictício · vídeo simulado':'Câmera simulada desativada'}</p></div><div class="self-preview">${avatar({name:db.settings.doctor,color:0})}<small>Você · demonstração</small></div><span class="call-timer" id="call-timer">00:00</span><div class="call-controls"><button data-action="toggle-mic" class="${callState.mic?'':'off'}" aria-label="${callState.mic?'Desativar':'Ativar'} microfone simulado">${icon('mic',17)}</button><button data-action="toggle-camera" class="${callState.camera?'':'off'}" aria-label="${callState.camera?'Desativar':'Ativar'} câmera simulada">${icon('video',17)}</button><button data-action="share-screen" aria-label="Simular compartilhamento de tela">${icon('screen',17)}</button><button data-action="end-call" class="end-call" aria-label="Encerrar demonstração">${icon('phone',17)}</button></div></div><div class="notice" style="margin-top:16px">${icon('shield',15)}Os controles demonstram o fluxo de atendimento. Seu microfone e sua câmera não são acessados.</div></section>${card('Anotações da sessão','Registre uma evolução demonstrativa.',`<div class="card-body"><div class="person-cell" style="margin-bottom:22px">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.procedure)}</small></span></div><label class="field"><span>Resumo do acompanhamento</span><textarea id="call-notes" rows="9" placeholder="Descreva o acompanhamento de exemplo...">${esc(callState.notes||'')}</textarea></label>${btn('Salvar no prontuário','save-call-note','record','primary','style="width:100%;margin-top:17px"')}</div>`)}</div>`}
const docTypes=['Declaração de comparecimento','Plano de tratamento','Termo de consentimento','Orientações de cuidado'];
function documentText(type,p){if(type==='Plano de tratamento')return `Paciente: ${p.name}\n\nPlanejamento proposto para apresentação:\n\n${p.treatments.map((t,i)=>`${i+1}. ${t.name} — ${money(t.value)} (${t.status})`).join('\n')||'Nenhum procedimento adicionado ao plano.'}\n\nTotal demonstrativo: ${money(p.treatments.reduce((s,t)=>s+t.value,0))}.\n\nOs valores e procedimentos são fictícios. Este documento não constitui uma proposta clínica real.`;if(type==='Termo de consentimento')return `Eu, ${p.name}, declaro que recebi explicações sobre as etapas de um planejamento odontológico fictício, incluindo alternativas e esclarecimento de dúvidas.\n\nEste texto é um exemplo de interface. Não substitui um termo elaborado para um tratamento real e não registra consentimento válido.\n\nLocal e data: São Paulo, ${prettyDate(today,{day:'numeric',month:'long',year:'numeric'})}.`;if(type==='Orientações de cuidado')return `Paciente: ${p.name}\n\nExemplo de material educativo para apresentação da plataforma.\n\n• Mantenha uma rotina de higiene bucal.\n• Siga as orientações individualizadas do seu profissional.\n• Compareça às consultas de acompanhamento.\n• Em caso de desconforto ou dúvida, procure seu dentista.\n\nEstas orientações são genéricas e demonstrativas. Não há avaliação ou prescrição individual neste sistema.`;return `Declaramos, exclusivamente para fins de demonstração da plataforma, que ${p.name} possui um atendimento fictício registrado em ${prettyDate(today,{day:'numeric',month:'long',year:'numeric'})}.\n\nEste documento não comprova comparecimento real e não possui validade clínica, trabalhista ou jurídica.`}
function paper(type,p,text){return `<div class="paper" id="document-paper"><div class="paper-top"><div>◡ Sorriso com IA<small>${esc(db.settings.clinic)} · DOCUMENTO DEMONSTRATIVO</small></div>${icon('tooth',30)}</div><h2>${esc(type)}</h2><p>${esc(text||documentText(type,p))}</p><div class="signature">${esc(db.settings.doctor)}<small>Assinatura ilustrativa · Sem validade profissional</small></div><p style="text-align:center;font-size:8px;color:#a4b292;margin-top:30px">DADOS FICTÍCIOS · GERADO EM AMBIENTE DE APRESENTAÇÃO</p></div>`}
function renderDocuments(){const p=patient(documentPatient);return heading('Documentos que acompanham o cuidado.','Crie, visualize e apresente documentos com poucos cliques.',btn('Novo documento','new-document','plus','primary'))+`<div class="two-columns"><section>${paper(documentType,p)}</section>${card('Preparar documento','Escolha um modelo e um paciente fictício.',`<div class="card-body"><label class="field"><span>Modelo</span><select id="document-type">${docTypes.map(t=>`<option ${t===documentType?'selected':''}>${t}</option>`).join('')}</select></label><label class="field" style="margin-top:20px"><span>Paciente</span><select id="document-patient">${patientOptions(documentPatient)}</select></label><label class="field" style="margin-top:20px"><span>Conteúdo do documento</span><textarea id="document-text" rows="8">${esc(documentText(documentType,p))}</textarea><small>Edite o texto antes de salvar ou imprimir.</small></label><div style="display:flex;gap:8px;margin-top:20px">${btn('Salvar documento','save-document','file','primary')}${btn('Imprimir / PDF','print-document','print')}</div><div class="notice" style="margin-top:22px;margin-bottom:0">${icon('info',16)}Documentos de demonstração, sem assinatura digital e sem validade jurídica.</div></div>`)}</div><div style="margin-top:22px">${card('Documentos salvos','Organização para cada etapa da jornada',`<div class="table-wrap"><table><thead><tr><th>Documento</th><th>Paciente</th><th>Data</th><th>Status</th><th></th></tr></thead><tbody>${db.documents.map(d=>`<tr><td><div class="person-cell"><span class="kpi-icon">${icon('file',16)}</span><strong>${esc(d.type)}</strong></div></td><td>${esc(patient(d.patient).name)}</td><td>${prettyDate(d.date)}</td><td>${badge(d.status)}</td><td>${btn('Visualizar','view-document','','',`data-id="${d.id}"`)}</td></tr>`).join('')}</tbody></table></div>`)}</div>`}
function financeStats(){const income=db.transactions.filter(t=>t.kind==='Receita'&&t.status==='Recebido').reduce((s,t)=>s+t.value,0);const expense=db.transactions.filter(t=>t.kind==='Despesa'&&t.status==='Pago').reduce((s,t)=>s+t.value,0);const pending=db.transactions.filter(t=>t.kind==='Receita'&&t.status==='Pendente').reduce((s,t)=>s+t.value,0);return {income,expense,pending,balance:income-expense}}
function transactionRows(){const list=db.transactions.filter(t=>financeFilter==='Todos'||(financeFilter==='Receitas'?t.kind==='Receita':financeFilter==='Despesas'?t.kind==='Despesa':t.status==='Pendente')).sort((a,b)=>b.date.localeCompare(a.date));return list.map(t=>`<tr><td><strong style="font-weight:500">${esc(t.description)}</strong><div class="muted" style="font-size:8px;margin-top:5px">${t.patient?esc(patient(t.patient).name):'Despesa da clínica'}</div></td><td>${prettyDate(t.date)}</td><td>${esc(t.method)}</td><td>${badge(t.status)}</td><td class="transaction-amount ${t.kind==='Despesa'?'expense':''}">${t.kind==='Despesa'?'−':''}${money(t.value)}</td><td>${t.status==='Pendente'?btn('Receber','receive-payment','check','',`data-id="${t.id}"`):`<span class="muted">${icon('check',14)}</span>`}</td></tr>`).join('')||'<tr><td colspan="6">Nenhum lançamento com este filtro.</td></tr>'}
function renderFinance(){const s=financeStats();return heading('Saúde financeira, com clareza.','Acompanhe entradas, despesas e recebimentos da demonstração.',`${btn('Exportar CSV','export-finance','download')}${btn('Novo lançamento','new-transaction','plus','primary')}`)+`<div class="kpi-grid">${kpi('Recebido',money(s.income),'wallet','receitas confirmadas')}${kpi('Despesas pagas',money(s.expense),'money','custos da clínica')}${kpi('Saldo demonstrativo',money(s.balance),'chart','recebido menos despesas')}${kpi('A receber',money(s.pending),'clock','pagamentos pendentes')}</div><div class="finance-chart-section">${card('Movimento da clínica','Visão do seu cuidado ao longo do tempo',`<div class="card-body" id="activity-chart">${activityChart()}</div>`,`<div class="segmented"><button data-action="chart-period" data-value="Semana" class="${chartPeriod==='Semana'?'active':''}">Semana</button><button data-action="chart-period" data-value="Mês" class="${chartPeriod==='Mês'?'active':''}">Mês</button></div>`)}</div>${card('Movimentações','Valores fictícios para apresentação',`<div class="table-wrap"><table><thead><tr><th>Descrição</th><th>Data</th><th>Forma de pagamento</th><th>Status</th><th>Valor</th><th></th></tr></thead><tbody id="finance-rows">${transactionRows()}</tbody></table></div>`,`<select id="finance-filter" style="width:135px" aria-label="Filtrar movimentações">${['Todos','Receitas','Despesas','Pendentes'].map(s=>`<option ${financeFilter===s?'selected':''}>${s}</option>`).join('')}</select>`)}<div class="notice" style="margin-top:20px">${icon('info',16)}Nenhum pagamento é processado. Os lançamentos são registros locais para demonstração.</div>`}
function renderReports(){const completed=db.appointments.filter(a=>a.status==='Concluído').length;return heading('Dados que ajudam a cuidar melhor.','Indicadores da demonstração e relatórios prontos para exportar.',btn('Exportar resumo','export-summary','download','primary'))+`<div class="kpi-grid">${kpi('Pacientes ativos',db.patients.filter(p=>p.status==='Ativo').length,'users','dos '+db.patients.length+' cadastrados')}${kpi('Atendimentos concluídos',completed,'check','na base de exemplo')}${kpi('Sorrisos planejados',db.simulations.length,'sparkles','prévias de demonstração')}${kpi('Planos cadastrados',db.patients.reduce((s,p)=>s+p.treatments.length,0),'record','procedimentos de exemplo')}</div><div class="report-status-section">${card('Status dos agendamentos','Distribuição dos dados da demonstração',`<div class="card-body">${statusDonut()}</div>`)}</div><div class="module-grid" style="margin-top:22px">${[['Pacientes','Lista completa de pacientes fictícios e contatos.','users','export-patients'],['Agenda','Todos os agendamentos, datas e status.','calendar','export-appointments']].map(([t,d,i,a])=>`<section class="report-box"><span class="kpi-icon">${icon(i,18)}</span><div><h3>${t}</h3><p>${d}</p>${btn('Baixar CSV',a,'download')}</div></section>`).join('')}</div>`}
function statusDonut(){const statuses=['Confirmado','Concluído','Pendente','Cancelado'];const counts=statuses.map(s=>db.appointments.filter(a=>a.status===s).length),total=Math.max(1,counts.reduce((s,c)=>s+c,0));let accum=0;const stops=counts.map((c,i)=>{const a=accum;accum+=c/total*100;return `${['#426c48','#a8bd82','#dfe8cc','#edf2e5'][i]} ${a}% ${accum}%`}).join(',');return `<div class="chart-donut"><div class="donut" style="background:conic-gradient(${stops})"><strong>${db.appointments.length}</strong></div><div class="donut-legend">${statuses.map((s,i)=>`<span><i></i>${s} <strong>${counts[i]}</strong></span>`).join('')}</div></div>`}
function renderSettings(){const s=db.settings;return heading('Do seu jeito.','Personalize o ambiente e prepare sua apresentação.')+`<div class="two-columns"><div>${card('Perfil da clínica','Estas informações aparecem nos documentos e na navegação.',`<form id="settings-form" class="card-body"><div class="form-grid"><label class="field full"><span>Nome da clínica</span><input name="clinic" required maxlength="60" value="${esc(s.clinic)}"></label><label class="field"><span>Profissional responsável</span><input name="doctor" required maxlength="60" value="${esc(s.doctor)}"></label><label class="field"><span>Especialidade</span><input name="specialty" maxlength="60" value="${esc(s.specialty)}"></label><label class="field"><span>Telefone de exemplo</span><input name="phone" maxlength="25" value="${esc(s.phone)}"></label><label class="field"><span>E-mail de exemplo</span><input name="email" type="email" maxlength="100" value="${esc(s.email)}"></label><label class="field full"><span>Endereço de exemplo</span><input name="address" maxlength="150" value="${esc(s.address)}"></label></div><button class="button primary" style="margin-top:24px" type="submit">${icon('check',14)}Salvar alterações</button></form>`)}</div><div>${card('Preferências','Ajustes simulados da plataforma.',`<div class="card-body"><div class="setting-row"><div><h3>Lembretes de consulta</h3><p>Simula o envio de lembretes, sem enviar mensagens.</p></div><button class="toggle ${s.reminders?'on':''}" data-action="toggle-setting" data-key="reminders" role="switch" aria-checked="${s.reminders}" aria-label="Lembretes de consulta"></button></div><div class="setting-row"><div><h3>Notificações no painel</h3><p>Ative os avisos locais de demonstração.</p></div><button class="toggle ${s.notifications?'on':''}" data-action="toggle-setting" data-key="notifications" role="switch" aria-checked="${s.notifications}" aria-label="Notificações"></button></div></div>`)}${card('Modo apresentação','Tudo pronto para a sua próxima conversa.',`<div class="card-body"><p class="muted" style="font-size:10px">Todos os dados são fictícios. As alterações ficam salvas neste navegador e podem ser restauradas a qualquer momento.</p><div style="display:grid;gap:10px;margin-top:20px">${btn('Iniciar tour guiado','tour','sparkles','primary')}${btn('Tela cheia','fullscreen','screen')}${btn('Restaurar dados de exemplo','reset-demo','refresh','danger')}</div></div>`,'','settings-section').replace('class="card settings-section"','class="card settings-section" style="margin-top:22px"')}</div></div>`}
const renderers={inicio:renderHome,pacientes:renderPatients,agenda:renderAgenda,prontuarios:renderRecords,paciente:renderPatient,sorriso:renderSmile,teleconsultas:renderTeleconsultas,documentos:renderDocuments,financeiro:renderFinance,relatorios:renderReports,configuracoes:renderSettings};
function render(){renderNav();$('#content').innerHTML=(renderers[route]||renderHome)();if(callState&&route==='teleconsultas')updateTimer();document.title=`${route==='paciente'?'Perfil do paciente':navItems.find(n=>n[0]===route)?.[2]||'Visão geral'} · Sorriso com IA`}
function navigate(r){if(!renderers[r])r='inicio';if(location.hash==='#'+r){route=r;render()}else location.hash=r;$('#sidebar').classList.remove('open')}
window.addEventListener('hashchange',()=>{route=location.hash.slice(1).split('?')[0]||'inicio';if(!renderers[route])route='inicio';render();window.scrollTo({top:0,behavior:'instant'})});
function openPatient(id,tab='visao'){selectedPatient=id;patientTab=tab;navigate('paciente')}
function openModal(title,body,actions='',large=false){$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Fechar janela">${icon('close',18)}</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}</section></div>`;setTimeout(()=>{const el=$('input:not([type=hidden]),select,textarea,button', $('.modal-body'));if(el)el.focus()},70)}
function closeModal(){$('#modal-root').innerHTML=''}
function field(label,name,value='',type='text',required=false,full=false,extra=''){return `<label class="field ${full?'full':''}"><span>${label}${required?' *':''}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`}
function patientModal(id){const p=id?patient(id):{};openModal(id?'Editar paciente':'Um novo sorriso na clínica',`<form id="patient-form" data-id="${id||''}"><div class="form-grid">${field('Nome completo','name',p.name,'text',true,true,'maxlength="80"')}${field('Data de nascimento','birth',p.birth||'1995-01-01','date',true,false,`max="${today}" min="1900-01-01"`)}<label class="field"><span>Status</span><select name="status"><option ${p.status==='Ativo'?'selected':''}>Ativo</option><option ${p.status==='Inativo'?'selected':''}>Inativo</option></select></label>${field('Telefone','phone',p.phone,'tel',true,false,'maxlength="25"')}${field('E-mail','email',p.email,'email',true,false,'maxlength="100"')}${field('Procedimento principal','procedure',p.procedure||'Avaliação inicial','text',true,false,'maxlength="80"')}${field('Plano','plan',p.plan||'Particular','text',false,false,'maxlength="60"')}${field('Alergias e atenção','allergies',p.allergies||'Sem alergias relatadas','text',false,true,'maxlength="200"')}<label class="field full"><span>Observações</span><textarea name="notes" rows="3" maxlength="1000">${esc(p.notes||'')}</textarea></label></div><p style="font-size:9px">Use apenas informações fictícias nesta demonstração.</p></form>`,`${btn('Cancelar','close-modal')}${`<button class="button primary" type="submit" form="patient-form">${icon('check',14)}${id?'Salvar alterações':'Cadastrar paciente'}</button>`}`)}
function appointmentModal(defaultPatient,type='Presencial'){openModal(type==='Teleconsulta'?'Agendar teleconsulta':'Novo agendamento',`<form id="appointment-form"><div class="form-grid"><label class="field full"><span>Paciente *</span><select name="patient">${patientOptions(defaultPatient||db.patients[0].id)}</select></label>${field('Data','date',selectedDate,'date',true)}${field('Horário','time','09:00','time',true)}<label class="field"><span>Duração</span><select name="duration"><option value="30">30 minutos</option><option value="45">45 minutos</option><option value="60">60 minutos</option></select></label><label class="field"><span>Modalidade</span><select name="type"><option ${type==='Presencial'?'selected':''}>Presencial</option><option ${type==='Teleconsulta'?'selected':''}>Teleconsulta</option></select></label>${field('Procedimento','procedure',type==='Teleconsulta'?'Acompanhamento online':'Avaliação de rotina','text',true,true,'maxlength="100"')}<label class="field"><span>Profissional</span><select name="professional"><option>${esc(db.settings.doctor)}</option><option>Dr. André Lima</option></select></label><label class="field"><span>Status</span><select name="status"><option>Confirmado</option><option>Pendente</option></select></label></div><p id="appointment-error" class="muted" role="alert"></p></form>`,`${btn('Cancelar','close-modal')}<button class="button primary" type="submit" form="appointment-form">${icon('check',14)}Salvar agendamento</button>`)}
function appointmentDetail(id){const a=db.appointments.find(a=>a.id===id),p=patient(a.patient);openModal('Detalhes do atendimento',`<div class="person-cell" style="margin-bottom:25px">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(a.procedure)}</small></span></div><div class="detail-grid">${[['Data',prettyDate(a.date,{day:'numeric',month:'long',year:'numeric'})],['Horário',`${a.time} · ${a.duration} min`],['Profissional',a.professional],['Modalidade',a.type]].map(([l,v])=>`<div class="detail-field"><small>${l}</small><span>${esc(v)}</span></div>`).join('')}</div><div style="margin-top:25px">${badge(a.status)}</div>`,`${a.status!=='Cancelado'&&a.status!=='Concluído'?btn('Cancelar consulta','cancel-appointment','','danger',`data-id="${id}"`):''}${a.status==='Pendente'?btn('Confirmar','confirm-appointment','check','',`data-id="${id}"`):''}${a.status!=='Cancelado'&&a.status!=='Concluído'?btn('Concluir atendimento','complete-appointment','check','primary',`data-id="${id}"`):btn('Fechar','close-modal')}`)}
function noteModal(id){openModal('Registrar evolução',`<form id="note-form" data-id="${id}"><div class="form-grid">${field('Título do registro','title','Consulta de acompanhamento','text',true,true,'maxlength="100"')}${field('Data','date',today,'date',true,true)}<label class="field full"><span>Evolução demonstrativa *</span><textarea name="text" rows="6" required maxlength="4000" placeholder="Registre as observações fictícias do atendimento..."></textarea></label></div></form>`,`${btn('Cancelar','close-modal')}<button class="button primary" type="submit" form="note-form">Salvar evolução</button>`)}
function treatmentModal(id){openModal('Adicionar procedimento ao plano',`<form id="treatment-form" data-id="${id}"><div class="form-grid">${field('Procedimento','name','','text',true,true,'maxlength="100"')}${field('Valor demonstrativo (R$)','value','350','number',true,false,'min="0" max="999999" step="0.01"')}<label class="field"><span>Status</span><select name="status"><option>Planejado</option><option>Em andamento</option><option>Concluído</option></select></label></div></form>`,`${btn('Cancelar','close-modal')}<button class="button primary" type="submit" form="treatment-form">Adicionar procedimento</button>`)}
function transactionModal(){openModal('Novo lançamento',`<form id="transaction-form"><div class="form-grid">${field('Descrição','description','','text',true,true,'maxlength="100"')}<label class="field"><span>Tipo</span><select name="kind"><option>Receita</option><option>Despesa</option></select></label>${field('Valor (R$)','value','350','number',true,false,'min="0.01" max="9999999" step="0.01"')}${field('Data','date',today,'date',true)}<label class="field"><span>Forma de pagamento</span><select name="method"><option>Pix</option><option>Cartão</option><option>Dinheiro</option><option>Transferência</option></select></label><label class="field"><span>Paciente (opcional)</span><select name="patient"><option value="">Sem vínculo</option>${patientOptions('none')}</select></label><label class="field"><span>Situação</span><select name="situation"><option value="paid">Já recebido / pago</option><option value="pending">Pendente</option></select></label></div><p style="font-size:9px">Registro de demonstração. Nenhuma cobrança será realizada.</p></form>`,`${btn('Cancelar','close-modal')}<button class="button primary" type="submit" form="transaction-form">Salvar lançamento</button>`)}
function searchModal(){window.DrHelp.open()}
function notifications(){openModal('O cuidado está em movimento',db.activity.map(a=>`<div class="activity-item"><span class="kpi-icon">${icon(a.icon,15)}</span><div><p>${esc(a.text)}</p><small>${prettyDate(a.date)} · Atividade demonstrativa</small></div></div>`).join('')||'<p>Nenhuma atividade ainda.</p>')}
function updateTimer(){if(!callState)return;const sec=Math.floor((Date.now()-callState.started)/1000);const el=$('#call-timer');if(el)el.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
function download(content,name,type='text/csv;charset=utf-8'){const blob=new Blob([content],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function csvCell(v){const raw=String(v??'');return '"'+(/^[=+\-@\t\r]/.test(raw)?"'"+raw:raw).replace(/"/g,'""')+'"'}
function exportCSV(kind){let headers,rows;if(kind==='patients'){headers=['Nome','E-mail fictício','Telefone fictício','Status','Procedimento'];rows=db.patients.map(p=>[p.name,p.email,p.phone,p.status,p.procedure])}else if(kind==='appointments'){headers=['Data','Horário','Paciente','Procedimento','Profissional','Modalidade','Status'];rows=db.appointments.map(a=>[a.date,a.time,patient(a.patient).name,a.procedure,a.professional,a.type,a.status])}else if(kind==='summary'){const s=financeStats();headers=['Indicador','Valor demonstrativo'];rows=[['Pacientes',db.patients.length],['Agendamentos',db.appointments.length],['Simulações',db.simulations.length]]}else{headers=['Descrição','Tipo','Paciente','Data','Valor (R$)','Status','Forma'];rows=db.transactions.map(t=>[t.description,t.kind,t.patient?patient(t.patient).name:'',t.date,t.value,t.status,t.method])}download('\ufeff'+[headers,...rows].map(r=>r.map(csvCell).join(';')).join('\r\n'),`sorriso-demo-${kind}-${today}.csv`);toast('Relatório demonstrativo exportado.')}
const tours=[{route:'inicio',title:'Sua clínica em um só olhar.',text:'Comece pelos indicadores, veja a agenda do dia e acompanhe os pacientes. Todos os dados desta apresentação são fictícios.'},{route:'pacientes',title:'Cada sorriso tem uma história.',text:'Abra o perfil de Mariana Oliveira, explore as evoluções, marque o odontograma e adicione procedimentos ao plano. Você também pode cadastrar novos pacientes fictícios.'},{route:'agenda',title:'Um dia de cuidado bem organizado.',text:'Navegue entre as datas, agende uma consulta, confirme ou conclua os atendimentos. Os dados ficam salvos neste navegador.'},{route:'sorriso',title:'Uma conversa visual sobre possibilidades.',text:'Ajuste a tonalidade e o alinhamento da ilustração. Arraste a divisória para comparar e salve uma prévia. O processamento de IA é simulado.'},{route:'teleconsultas',title:'Presença que vai além do consultório.',text:'Entre na sala demonstrativa, experimente os controles e registre uma evolução. A sessão não acessa câmera ou microfone.'},{route:'documentos',title:'Do planejamento à organização.',text:'Gere documentos de exemplo, imprima em PDF, acompanhe o financeiro e exporte relatórios. Tudo pronto para você apresentar a jornada completa.'}];
function showTour(){const t=tours[tourStep];navigate(t.route);$('#tour-root').innerHTML=`<div class="tour-overlay"><section class="tour-panel" role="dialog" aria-modal="true" aria-label="Tour de apresentação"><div style="display:flex;justify-content:space-between;align-items:center"><span class="eyebrow">TOUR DA PLATAFORMA · ${tourStep+1} DE ${tours.length}</span><button class="icon-button" data-action="end-tour" aria-label="Fechar tour">${icon('close',17)}</button></div><h2>${t.title}</h2><p>${t.text}</p><div class="tour-actions"><div class="tour-dots">${tours.map((t,i)=>`<i class="${i===tourStep?'active':''}"></i>`).join('')}</div><div style="display:flex;gap:8px">${tourStep>0?btn('Voltar','prev-tour','','ghost'):''}${btn(tourStep===tours.length-1?'Explorar plataforma':'Próxima etapa','next-tour','arrow','primary')}</div></div></section></div>`}
document.addEventListener('click',async e=>{const routeEl=e.target.closest('[data-route]');if(routeEl){navigate(routeEl.dataset.route);return}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;switch(a){
case'menu':$('#sidebar').classList.toggle('open');break;
case'close-modal':closeModal();break;
case'new-patient':patientModal();break;
case'edit-patient':patientModal(id);break;
case'patient':closeModal();openPatient(id);break;
case'open-record':openPatient(id,'evolucao');break;
case'patient-tab':patientTab=el.dataset.tab;render();break;
case'patient-view':patientView=el.dataset.value;render();break;
case'new-appointment':appointmentModal(el.dataset.patient);break;
case'new-teleconsult':appointmentModal(null,'Teleconsulta');break;
case'appointment-detail':appointmentDetail(id);break;
case'select-day':selectedDate=el.dataset.date;render();break;
case'prev-day':selectedDate=addDay(selectedDate,-1);render();break;
case'next-day':selectedDate=addDay(selectedDate,1);render();break;
case'today':selectedDate=today;render();break;
case'confirm-appointment':case'cancel-appointment':case'complete-appointment':{const ap=db.appointments.find(x=>x.id===id);ap.status=a==='confirm-appointment'?'Confirmado':a==='cancel-appointment'?'Cancelado':'Concluído';if(ap.status==='Concluído'){const p=patient(ap.patient);p.last=ap.date;p.history.unshift({date:ap.date,title:ap.procedure,text:'Atendimento concluído na demonstração. Registro automático fictício.'})}activity(`Atendimento de ${patient(ap.patient).name}: ${ap.status.toLowerCase()}.`,'calendar');closeModal();render();toast('Agendamento atualizado.');break}
case'new-note':noteModal(id);break;
case'new-treatment':treatmentModal(id);break;
case'tooth':{const p=patient(selectedPatient),n=el.dataset.tooth;p.teeth[n]=p.teeth[n]==='marked'?'treatment':p.teeth[n]==='treatment'?'':'marked';save();el.className='tooth '+p.teeth[n];el.setAttribute('aria-label',`Dente ${n}: ${p.teeth[n]==='marked'?'acompanhamento':p.teeth[n]==='treatment'?'tratamento':'íntegro'}`);toast(`Dente ${n}: ${p.teeth[n]==='marked'?'acompanhamento':p.teeth[n]==='treatment'?'tratamento':'íntegro'}.`);break}
case'chart-period':chartPeriod=el.dataset.value;render();break;
case'search':searchModal();break;
case'notifications':notifications();break;
case'shade':smile.shade=el.dataset.value;smile.generated=false;render();break;
case'reset-photo':smile.photo=null;smile.generated=false;render();break;
case'generate-smile':{el.disabled=true;el.textContent='Preparando a demonstração...';$('#simulation-progress').innerHTML='<div class="loading-bar"><span></span></div>';setTimeout(()=>{smile.generated=true;if(route==='sorriso'){render();toast('Prévia ilustrativa pronta. Arraste para comparar.')}},1800);break}
case'save-simulation':{if(!smile.generated)return;const s={id:uid('s'),patient:smile.patient,date:today,shade:smile.shade,alignment:smile.alignment,shape:smile.shape};db.simulations.unshift(s);activity(`Prévia ilustrativa de ${patient(s.patient).name} salva.`,'sparkles');render();toast('Prévia salva na galeria de demonstração.');break}
case'open-simulation':{const s=db.simulations.find(x=>x.id===id);smile={...smile,...s,generated:true,photo:null};render();toast('Planejamento carregado no estúdio.');window.scrollTo({top:0,behavior:'smooth'});break}
case'start-call':{const ap=db.appointments.find(x=>x.id===id);callState={patient:ap.patient,appointment:ap.id,started:Date.now(),mic:true,camera:true,notes:''};clearInterval(callTimer);callTimer=setInterval(updateTimer,1000);render();break}
case'toggle-mic':callState.notes=$('#call-notes')?.value||'';callState.mic=!callState.mic;render();toast(callState.mic?'Microfone simulado ativado.':'Microfone simulado desativado.');break;
case'toggle-camera':callState.notes=$('#call-notes')?.value||'';callState.camera=!callState.camera;render();break;
case'share-screen':toast('Compartilhamento de tela simulado. Nenhuma tela está sendo transmitida.');break;
case'save-call-note':{const text=$('#call-notes').value.trim();if(!text){toast('Escreva uma anotação antes de salvar.');return}patient(callState.patient).history.unshift({date:today,title:'Teleconsulta demonstrativa',text});callState.notes=text;save();toast('Evolução salva no prontuário do paciente.');break}
case'end-call':{callState.notes=$('#call-notes')?.value||'';openModal('Encerrar sessão demonstrativa?',`<p>A sala será fechada. ${callState.notes?'Você pode salvar suas anotações no prontuário antes de encerrar.':'Nenhum atendimento real foi realizado.'}</p>`,`${btn('Continuar na sala','close-modal')}${btn('Encerrar e salvar','confirm-end-call','check','primary')}`);break}
case'confirm-end-call':{if(callState.notes.trim())patient(callState.patient).history.unshift({date:today,title:'Resumo da teleconsulta demonstrativa',text:callState.notes});const ap=db.appointments.find(x=>x.id===callState.appointment);if(ap)ap.status='Concluído';activity(`Teleconsulta demonstrativa de ${patient(callState.patient).name} concluída.`,'video');clearInterval(callTimer);callState=null;closeModal();render();toast('Sessão demonstrativa concluída.');break}
case'new-document':documentType='Declaração de comparecimento';navigate('documentos');toast('Selecione o paciente e edite o modelo ao lado.');break;
case'save-document':{const text=$('#document-text').value.trim();if(!text){toast('Preencha o conteúdo do documento.');return}db.documents.unshift({id:uid('d'),patient:documentPatient,type:documentType,date:today,status:'Emitido',text});activity(`Documento de ${patient(documentPatient).name} salvo.`,'file');render();toast('Documento demonstrativo salvo.');break}
case'print-document':{const text=$('#document-text')?.value;$('#document-paper').outerHTML=paper(documentType,patient(documentPatient),text);window.print();break}
case'view-document':{const d=db.documents.find(x=>x.id===id);openModal(d.type,paper(d.type,patient(d.patient),d.text),btn('Baixar texto','download-document','download','primary',`data-id="${id}"`),true);break}
case'download-document':{const d=db.documents.find(x=>x.id===id);download(`${db.settings.clinic}\nDOCUMENTO DEMONSTRATIVO — SEM VALIDADE\n\n${d.type}\nPaciente: ${patient(d.patient).name}\nData: ${d.date}\n\n${d.text}\n\n${db.settings.doctor}\nAssinatura ilustrativa.`,`${d.type.toLowerCase().replaceAll(' ','-')}-demo.txt`,'text/plain;charset=utf-8');toast('Documento de exemplo baixado.');break}
case'new-transaction':transactionModal();break;
case'receive-payment':{const t=db.transactions.find(x=>x.id===id);t.status=t.kind==='Receita'?'Recebido':'Pago';activity(`Lançamento atualizado: ${t.description}.`,'wallet');render();toast('Pagamento marcado na demonstração. Nenhuma cobrança realizada.');break}
case'export-patients':exportCSV('patients');break;
case'export-appointments':exportCSV('appointments');break;
case'export-finance':exportCSV('finance');break;
case'export-summary':exportCSV('summary');break;
case'toggle-setting':{const key=el.dataset.key;db.settings[key]=!db.settings[key];save();el.classList.toggle('on',db.settings[key]);el.setAttribute('aria-checked',String(db.settings[key]));toast('Preferência de demonstração atualizada.');break}
case'reset-demo':openModal('Restaurar a demonstração?',`<p>Os cadastros e alterações feitos neste navegador serão substituídos pelos exemplos iniciais. Isso não afeta nenhum sistema real.</p>`,`${btn('Cancelar','close-modal')}${btn('Restaurar exemplos','confirm-reset','refresh','danger')}`);break;
case'confirm-reset':db=seed();save();callState=null;clearInterval(callTimer);smile={patient:'p5',shade:'B1',alignment:65,shape:50,compare:50,photo:null,generated:false};selectedDate=today;selectedPatient='p1';documentPatient='p1';patientQuery='';patientStatus='Todos';closeModal();navigate('inicio');render();toast('Demonstração restaurada. Tudo pronto para apresentar.');break;
case'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('Use o modo tela cheia do seu navegador.')}break;
case'tour':tourStep=0;showTour();break;
case'next-tour':tourStep++;if(tourStep>=tours.length){$('#tour-root').innerHTML='';tourStep=-1;toast('Pronto para apresentar. Explore os módulos no menu.')}else showTour();break;
case'prev-tour':tourStep=Math.max(0,tourStep-1);showTour();break;
case'end-tour':$('#tour-root').innerHTML='';tourStep=-1;break;
}});
document.addEventListener('input',e=>{const el=e.target;switch(el.id){case'patient-search':patientQuery=el.value;$('#patients-list').innerHTML=patientCards();break;case'compare-slider':smile.compare=Number(el.value);$('#smile-stage').style.setProperty('--compare',smile.compare+'%');break;case'alignment':case'shape':{smile[el.id]=Number(el.value);smile.generated=false;$('#'+el.id+'-value').textContent=el.value+'%';const stage=$('#smile-stage');stage.innerHTML=smileStage();const saveButton=$('[data-action="save-simulation"]');if(saveButton)saveButton.disabled=true;break}case'document-text':{const p=$('#document-paper>p');if(p)p.textContent=el.value;break}case'call-notes':if(callState)callState.notes=el.value;break}});
document.addEventListener('change',e=>{const el=e.target;switch(el.id){case'patient-status':patientStatus=el.value;$('#patients-list').innerHTML=patientCards();break;case'agenda-status':agendaStatus=el.value;render();break;case'finance-filter':financeFilter=el.value;$('#finance-rows').innerHTML=transactionRows();break;case'smile-patient':smile.patient=el.value;break;case'document-type':documentType=el.value;render();break;case'document-patient':documentPatient=el.value;render();break;case'smile-photo':{const f=el.files[0];if(!f)return;if(!['image/jpeg','image/png'].includes(f.type)||f.size>4*1024*1024){toast('Escolha uma imagem JPG ou PNG com até 4 MB.');return}const reader=new FileReader();reader.onload=()=>{smile.photo=reader.result;smile.generated=false;render();toast('Imagem carregada apenas para prévia local.')};reader.readAsDataURL(f);break}}});
document.addEventListener('submit',e=>{const f=e.target;if(!['patient-form','appointment-form','note-form','treatment-form','transaction-form','settings-form'].includes(f.id))return;e.preventDefault();const v=Object.fromEntries(new FormData(f));switch(f.id){case'patient-form':{const editing=f.dataset.id;const p=editing?patient(editing):{id:uid('p'),color:db.patients.length%4,last:today,teeth:{},history:[],treatments:[]};Object.assign(p,v);if(!editing)db.patients.unshift(p);activity(`${p.name}: cadastro ${editing?'atualizado':'criado'}.`,'users');closeModal();render();toast(editing?'Cadastro atualizado.':'Paciente fictício cadastrado.');break}case'appointment-form':{const clash=db.appointments.some(a=>a.date===v.date&&a.professional===v.professional&&a.status!=='Cancelado'&&Math.abs(timeMinutes(a.time)-timeMinutes(v.time))<((timeMinutes(a.time)<=timeMinutes(v.time))?Number(a.duration):Number(v.duration)));if(clash){$('#appointment-error').textContent='Este profissional já tem uma consulta nesse intervalo. Escolha outro horário.';return}db.appointments.push({...v,id:uid('a'),duration:Number(v.duration)});selectedDate=v.date;activity(`Consulta de ${patient(v.patient).name} agendada para ${prettyDate(v.date)} às ${v.time}.`,'calendar');closeModal();navigate(v.type==='Teleconsulta'?'teleconsultas':'agenda');render();toast('Consulta agendada na demonstração.');break}case'note-form':{const p=patient(f.dataset.id);p.history.unshift({title:v.title,date:v.date,text:v.text});p.last=v.date;save();closeModal();patientTab='evolucao';render();toast('Evolução salva no prontuário.');break}case'treatment-form':patient(f.dataset.id).treatments.push({...v,value:Number(v.value)});save();closeModal();render();toast('Procedimento adicionado ao plano.');break;case'transaction-form':{const {situation,...data}=v;db.transactions.unshift({...data,id:uid('f'),value:Number(v.value),status:situation==='pending'?'Pendente':v.kind==='Receita'?'Recebido':'Pago'});activity(`Lançamento demonstrativo: ${v.description}.`,'wallet');closeModal();render();toast('Lançamento salvo.');break}case'settings-form':Object.assign(db.settings,v);save();render();toast('Informações da clínica atualizadas.');break}});
function timeMinutes(t){const[h,m]=t.split(':').map(Number);return h*60+m}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchModal()}if(e.key==='Escape'){closeModal();$('#tour-root').innerHTML='';$('#sidebar').classList.remove('open')}if(e.key==='Tab'&&$('.modal')){const list=$$('button,a,input,select,textarea', $('.modal')).filter(el=>!el.disabled&&el.type!=='hidden');if(list.length){if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus()}}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-overlay'))closeModal();if(innerWidth<801&&$('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar')&&!e.target.closest('[data-action="menu"]'))$('#sidebar').classList.remove('open')});
route=location.hash.slice(1).split('?')[0]||'inicio';if(!renderers[route])route='inicio';render();save();
